INSERT INTO hb_sessions (phone, active, started_at, last_active)
VALUES ('{{ String($('Clean Message').first().json.from).replace(/\D/g,'') }}', 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE
  started_at  = IF(hb_sessions.active = 1 AND hb_sessions.last_active > NOW() - INTERVAL 3 HOUR, hb_sessions.started_at, NOW()),
  active      = 1,
  last_active = NOW();
{{ (() => { const j = $('Clean Message').first().json; const ph = String(j.from).replace(/\D/g,''); return (j.idtok && j.idtok.length) ? "INSERT INTO hb_msg_tokens (phone, token_hash) VALUES " + j.idtok.map(t => "('" + ph + "', SHA2('" + t + "', 256))").join(',') + ";" : ""; })() }}
SELECT 1 AS ok;

