'<style>body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f3f5f8;margin:0;padding:16px;color:#1b2430}' +
'.card{max-width:460px;margin:20px auto;background:#fff;border-radius:14px;padding:22px;box-shadow:0 2px 12px rgba(0,0,0,.08)}' +
'h2{margin:0 0 4px;font-size:20px}.sub{color:#6b7683;font-size:13px;margin-bottom:12px}' +
'.badge{display:inline-block;padding:4px 10px;border-radius:99px;font-size:13px;font-weight:600;margin:4px 0 8px}' +
'.p{background:#fff3d6;color:#8a5a00}.c{background:#dff5e7;color:#14703a}.r{background:#fde2e2;color:#a12626}.g{background:#e8ebef;color:#4a5560}' +
