'</style></head><body><div class="card">' + inner + '</div></body></html>';
}
const STATUS = { PENDING: ['p', 'Waiting for approval'], CONFIRMED: ['c', 'Confirmed'], REJECTED: ['r', 'Rejected'], EXPIRED: ['g', 'Expired'], CANCELLED: ['g', 'Cancelled by guest'] };
function details(x) {
