    '<tr><td>Check-in</td><td>' + esc(x.ci) + '</td></tr>' +
    '<tr><td>Check-out</td><td>' + esc(x.co) + ', 11:00 AM<br><small>' + esc(x.days) + ' day(s)</small></td></tr>' +
    '<tr><td>Guests</td><td>' + esc(x.guests) + '</td></tr>' +
    '<tr><td>Total</td><td><b>' + esc(inr(x.total)) + '</b><br><small>pay at hotel</small></td></tr>' +
    '<tr><td>Requested</td><td>' + esc(x.requested_at) + '</td></tr></table>';
}
function head(x) {
  const s = STATUS[x.status] || ['g', x.status];
  return '<h2>Booking #' + esc(x.booking_code) + '</h2><span class="badge ' + s[0] + '">' + esc(s[1]) + '</span>';
}
const invalid = page('Invalid link', '<h2>Invalid link</h2><div class="sub">This approval link is not valid.</div>');

if (MODE === 'page') {
